"""Write results_search/DELIVERY_STATUS.md: what is in results_search/ right now, per RC and per batch.   python tools/delivery_status.py"""
import collections, json, os, statistics, sys
sys.path.insert(0, os.path.dirname(__file__)); from runs_scan import scan
R = "results_search"; rows = collections.defaultdict(list)
for rc, b, d, s in scan(R): rows[(rc, b)].append(s)
meta = json.load(open(f"{R}/rc_status.json")) if os.path.exists(f"{R}/rc_status.json") else {}
L = ["# Delivery status (generated by tools/delivery_status.py)", "", "## The 20 RCs", "", "`current` = without the batches that a later batch replaces (`superseded` in rc_status.json); the other columns count every run folder.", "",
     "| RC | scene | where the data is | runs | PASS | FAIL | INVALID | median recorded pre-cue s | short_history (<3 s) | current runs | current PASS | current FAIL | current INVALID | current short |", "|---|---|---|---|---|---|---|---|---|---|---|---|---|---|"]
per = collections.defaultdict(list)
for (rc, b), v in rows.items(): per[rc] += v
tot = collections.Counter()
for n in range(1, 21):
    rc = f"rc{n:02d}"; v = per.get(rc, []); mt = meta.get(rc, {})
    lab = collections.Counter(s.get("label") for s in v); hs = [s["history_s"] for s in v if s.get("history_s") is not None]
    sup = set(mt.get("superseded", [])); cur = [s for (r2, b), vv in rows.items() if r2 == rc and b.split("/")[0] not in sup for s in vv]; cl = collections.Counter(s.get("label") for s in cur)
    L.append(f"| {rc.upper()} | {mt.get('scene', '')} | {mt.get('where', 'run folders in results_search/%s/carla/' % rc if v else 'MISSING')} | {len(v)} | {lab['PASS']} | {lab['FAIL']} | {lab['INVALID']} | "
             f"{round(statistics.median(hs), 2) if hs else '-'} | {sum(1 for s in v if s.get('short_history'))} | {len(cur)} | {cl['PASS']} | {cl['FAIL']} | {cl['INVALID']} | {sum(1 for s in cur if s.get('short_history'))} |")
    tot.update(lab); tot["n"] += len(v)
L += ["", f"Total: {tot['n']} run folders, PASS {tot['PASS']}, FAIL {tot['FAIL']}, INVALID {tot['INVALID']}.", "", "## Per batch", "",
      "| RC | batch | runs | PASS | FAIL | INVALID | median pre-cue s | pass rule |", "|---|---|---|---|---|---|---|---|"]
for (rc, b), v in sorted(rows.items()):
    lab = collections.Counter(s.get("label") for s in v); hs = [s["history_s"] for s in v if s.get("history_s") is not None]
    L.append(f"| {rc} | {b} | {len(v)} | {lab['PASS']} | {lab['FAIL']} | {lab['INVALID']} | {round(statistics.median(hs), 2) if hs else '-'} | {','.join(sorted({s.get('pass_rule_id') or '?' for s in v}))} |")
open(f"{R}/DELIVERY_STATUS.md", "w").write("\n".join(L) + "\n"); print("\n".join(L))
